import re
domain = "td-group.test-page.site"

def extract_links(fname):
    with open(fname, encoding='utf-8', errors='replace') as f:
        html = f.read()
    hrefs = re.findall(r'href=["\']([^"\']+)["\']', html)
    internal = set()
